#include <gst/gst.h>
#include <cstdio>
int main(int argc,char** argv){gst_init(&argc,&argv);if(argc!=2 && argc!=3)return 2;guint64 seconds=20;if(argc==3){gchar* end=nullptr;seconds=g_ascii_strtoull(argv[2],&end,10);if(!end||*end||seconds<1||seconds>600)return 2;}GError* e=nullptr;auto p=gst_parse_launch(argv[1],&e);if(e){fprintf(stderr,"%s\n",e->message);g_error_free(e);if(p)gst_object_unref(p);return 3;}auto bus=gst_element_get_bus(p);gst_element_set_state(p,GST_STATE_PLAYING);auto m=gst_bus_timed_pop_filtered(bus,seconds*GST_SECOND,(GstMessageType)(GST_MESSAGE_ERROR|GST_MESSAGE_EOS));int rc=0;if(!m){fprintf(stderr,"Timed out before EOS\n");rc=4;}else if(GST_MESSAGE_TYPE(m)==GST_MESSAGE_ERROR){gchar* debug=nullptr;gst_message_parse_error(m,&e,&debug);fprintf(stderr,"%s %s\n",e->message,debug?debug:"");g_error_free(e);g_free(debug);rc=5;}else puts("EOS");if(m)gst_message_unref(m);gst_element_set_state(p,GST_STATE_NULL);gst_object_unref(bus);gst_object_unref(p);return rc;}
